export interface Asset {
  code: string;
  label: string;
  cost: number;
}

export interface AssetRegister {
  lines: readonly string[];
  totalCost: number;
}

export function buildAssetRegister(assets: readonly Asset[]): AssetRegister {
  const seen = new Set<string>();
  for (const asset of assets) {
    if (asset.code.trim() === "" || asset.label.trim() === "") {
      throw new RangeError("code and label must not be empty");
    }
    if (!Number.isFinite(asset.cost) || asset.cost < 0) {
      throw new RangeError("cost must be finite and non-negative");
    }
    if (seen.has(asset.code)) throw new RangeError("duplicate asset code");
    seen.add(asset.code);
  }

  const ordered = [...assets].sort((a, b) =>
    a.code < b.code ? 1 : a.code > b.code ? -1 : 0
  );
  return {
    lines: ordered.map((asset) => asset.code + "|" + asset.label + "|" + asset.cost.toFixed(2)),
    totalCost: assets.reduce((sum, asset) => sum + asset.cost, 0)
  };
}

