import { buildAssetRegister } from './solution';
import type { Asset } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal<T>(actual: T, expected: T, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function arrayEqual(actual: readonly string[], expected: readonly string[], message: string): void {
  assert(actual.length === expected.length && actual.every((v, i) => v === expected[i]), message);
}
function throwsRange(action: () => void, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  assert(error instanceof RangeError, message);
}

const empty = buildAssetRegister([]);
arrayEqual(empty.lines, [], 'empty input has no lines');
equal(empty.totalCost, 0, 'empty input has zero total');

const assets: Asset[] = [
  { code: 'a', label: 'lower', cost: 2.5 },
  { code: 'B', label: 'upper', cost: 1.25 },
  { code: 'A', label: 'zero', cost: 0 }
];
const before = assets.map((asset) => ({ ...asset }));
const result = buildAssetRegister(assets);
arrayEqual(result.lines, ['A|zero|0.00', 'B|upper|1.25', 'a|lower|2.50'], 'lines are sorted and formatted');
equal(result.totalCost, 3.75, 'costs are summed numerically');
assert(assets.length === before.length && assets.every((asset, i) => asset.code === before[i].code && asset.label === before[i].label && asset.cost === before[i].cost), 'input is not mutated');

const first = buildAssetRegister(assets);
const second = buildAssetRegister(assets);
assert(first.lines !== second.lines, 'each result has a newly allocated lines array');
(assets[0] as { label: string }).label = 'changed later';
arrayEqual(result.lines, ['A|zero|0.00', 'B|upper|1.25', 'a|lower|2.50'], 'result does not alias input elements');

throwsRange(() => buildAssetRegister([{ code: '', label: 'x', cost: 1 }]), 'empty code rejected');
throwsRange(() => buildAssetRegister([{ code: '  ', label: 'x', cost: 1 }]), 'whitespace code rejected');
throwsRange(() => buildAssetRegister([{ code: 'x', label: '\t', cost: 1 }]), 'whitespace label rejected');
throwsRange(() => buildAssetRegister([{ code: 'x', label: 'x', cost: -0.01 }]), 'negative cost rejected');
throwsRange(() => buildAssetRegister([{ code: 'x', label: 'x', cost: Number.NaN }]), 'NaN cost rejected');
throwsRange(() => buildAssetRegister([{ code: 'x', label: 'x', cost: Number.POSITIVE_INFINITY }]), 'infinite cost rejected');
throwsRange(() => buildAssetRegister([{ code: 'dup', label: 'one', cost: 1 }, { code: 'dup', label: 'two', cost: 2 }]), 'duplicate code rejected');

